class GenerateLoanLetterAndAgreementModule_AutoGenerated {
  /*choose a loan request which id equals the request id,
   *if exist,
   *then create a new approval letter and set it's content to "ApprovalLetterContent"
   *and
   *save it
   *and
   *attach it to the loan request
   *then set the loan request to the current loan request*/
  genereateApprovalLetter(id: number): boolean {
    /*Definition Start*/
    let CurrentLoanRequest: LoanRequest = l({
      logic: () => undefined,
      description: "null",
    }).build().pass;
    let chosenLoanRequest: LoanRequest = l({
      logic: () =>
        CurrentLoanRequests.find(
          (lr: any) =>
            l({
              logic: () => lr.RequestID === id,
              description: "lr.RequestID=id",
            }).build().pass,
        ),
      description: "CurrentLoanRequests->any(lr|lr.RequestID=id)",
    }).build().pass;
    /*Definition End*/

    /*Precondition Start*/
    const { errorMessage: preconditionErrorMessage, pass: isPreconditionPass } =
      l({
        logic: () => StandardOPs.oclIsUndefined(chosenLoanRequest) === false,
        description: "chosenLoanRequest.oclIsUndefined()=false",
      }).build();
    if (!isPreconditionPass) {
      throw new PreconditionError(preconditionErrorMessage);
    }
    /*Precondition End*/

    /*Postcondition Start*/
    let newApprovalLetter: ApprovalLetter;
    return l({
      execute: () => (newApprovalLetter = new ApprovalLetter()),
      description: "newApprovalLetter.oclIsNew()",
    })
      .and({
        execute: () => getRepository(ApprovalLetter).push(newApprovalLetter),
        description:
          "ApprovalLetter.allInstance()->includes(newApprovalLetter)",
      })
      .and({
        execute: () => (newApprovalLetter.Content = "ApprovalLetterContent"),
        description: 'newApprovalLetter.Content="ApprovalLetterContent"',
      })
      .and({
        execute: () =>
          (chosenLoanRequest.AttachedApprovalLetter = newApprovalLetter),
        description:
          "chosenLoanRequest.AttachedApprovalLetter=newApprovalLetter",
      })
      .and({
        execute: () => (CurrentLoanRequest = chosenLoanRequest),
        description: "CurrentLoanRequest=chosenLoanRequest",
      })
      .and({
        execute: () => true,
        description: "result=true",
      })
      .build().value;
    /*Postcondition End*/
  }
}
export { GenerateLoanLetterAndAgreementModule_AutoGenerated };

